Lemma fp_step_fclass : forall (fx : FPState) segs regs pc mem rom w fmt rd rs1,
  fetch_word segs pc = Some w -> is_ecall w = false ->
  decode_any w = Some (Fclass fmt rd rs1, 4%Z) ->
  RiscvSemantics.step segs (@mkst fx regs pc mem rom) =
  MachineOk (@mkst fx (if bv_eqb rd 0 then regs
                       else regupd regs rd (Z_to_bv 64 (fp_class (fp_format fmt)
                              (match fmt with FMT_S => bv_unsigned (unbox_s (reg_get (@fp_regs fx) rs1)) | FMT_D => bv_unsigned (reg_get (@fp_regs fx) rs1) end))))
               (v_addi pc 4) mem rom).
Proof.
